-- PART 05: 종합 투자판단, 종목판단, 변경이력, 추가매수, 재매수

DROP VIEW tb_inv_dec;
ALTER TABLE "TB_INV_DEC" RENAME COLUMN "ID" TO "INV_DEC_ID"; ALTER TABLE "TB_INV_DEC" RENAME COLUMN "DEC_DT" TO "BASE_DT"; ALTER TABLE "TB_INV_DEC" RENAME COLUMN "MKT_SCORE" TO "MKT_SCR"; ALTER TABLE "TB_INV_DEC" RENAME COLUMN "SENT_RISK_SCORE" TO "RISK_SCR";
ALTER TABLE "TB_INV_DEC" ADD COLUMN "CALC_SEQ" INTEGER DEFAULT 1,ADD COLUMN "ACCT_ID" BIGINT,ADD COLUMN "MKT_SNAP_CD" VARCHAR(30) DEFAULT 'GLOBAL',ADD COLUMN "SENT_SCR" NUMERIC(10,4),ADD COLUMN "RISK_GRADE" VARCHAR(20),ADD COLUMN "CASH_AMT" NUMERIC(20,4),ADD COLUMN "RSV_CASH_AMT" NUMERIC(20,4),ADD COLUMN "TOT_AST_AMT" NUMERIC(20,4),ADD COLUMN "CASH_RT" NUMERIC(10,4),ADD COLUMN "TGT_CASH_RT" NUMERIC(10,4),ADD COLUMN "BUY_CAP_AMT" NUMERIC(20,4),ADD COLUMN "REG_BUY_BGT_AMT" NUMERIC(20,4),ADD COLUMN "ADD_BUY_BGT_AMT" NUMERIC(20,4),ADD COLUMN "REG_BUY_TOT_AMT" NUMERIC(20,4),ADD COLUMN "ADD_BUY_TOT_AMT" NUMERIC(20,4),ADD COLUMN "RSV_ADD_AMT" NUMERIC(20,4),ADD COLUMN "OVR_DEC_SIG" VARCHAR(30),ADD COLUMN "EXEC_YN" CHAR(1) DEFAULT 'N',ADD COLUMN "EXEC_RSN" VARCHAR(1000),ADD COLUMN "CONF_RT" NUMERIC(10,4),ADD COLUMN "KEY_RSN" VARCHAR(2000),ADD COLUMN "DATA_STS" VARCHAR(20),ADD COLUMN "RULE_VER_NO" INTEGER DEFAULT 1,ADD COLUMN "LATEST_YN" CHAR(1) DEFAULT 'Y',ADD COLUMN "CALC_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,ADD COLUMN "CRT_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,ADD COLUMN "CRT_USR_ID" VARCHAR(50);
UPDATE "TB_INV_DEC" SET "SENT_SCR"="RISK_SCR","RISK_GRADE"=CASE WHEN "RISK_SCR">=75 THEN 'CRITICAL' WHEN "RISK_SCR">=50 THEN 'HIGH' WHEN "RISK_SCR">=25 THEN 'MEDIUM' ELSE 'LOW' END,"REG_BUY_BGT_AMT"="TOT_MIN_BUY_AMT","REG_BUY_TOT_AMT"="TOT_RCM_BUY_AMT","RSV_ADD_AMT"="NEW_RSV_CASH","ADD_BUY_BGT_AMT"="AVAIL_ADD_BUY_CASH","OVR_DEC_SIG"=CASE WHEN "MKT_REGIME" IN ('CRASH_RISK') THEN 'PAUSE_BUY' WHEN "MKT_REGIME"='STRONG_CORRECTION' THEN 'SELECTIVE_ADD_BUY' ELSE 'KEEP_REGULAR_BUY' END,"CONF_RT"=80,"DATA_STS"='FRESH',"CALC_DTTM"="REG_DT" AT TIME ZONE 'Asia/Seoul',"CRT_DTTM"="REG_DT" AT TIME ZONE 'Asia/Seoul',"CRT_USR_ID"='SYSTEM';
WITH r AS (SELECT "INV_DEC_ID",row_number() OVER(PARTITION BY "BASE_DT",COALESCE("ACCT_ID",0),"MKT_SNAP_CD" ORDER BY "INV_DEC_ID") rn,count(*) OVER(PARTITION BY "BASE_DT",COALESCE("ACCT_ID",0),"MKT_SNAP_CD") cnt FROM "TB_INV_DEC") UPDATE "TB_INV_DEC" d SET "CALC_SEQ"=r.rn,"LATEST_YN"=CASE WHEN r.rn=r.cnt THEN 'Y' ELSE 'N' END FROM r WHERE r."INV_DEC_ID"=d."INV_DEC_ID";
ALTER TABLE "TB_STK_DEC" DROP CONSTRAINT "tb_investment_stock_decision_investment_decision_id_fkey";
ALTER TABLE "TB_INV_DEC" DROP CONSTRAINT "tb_investment_decision_pkey";
ALTER TABLE "TB_INV_DEC" ALTER COLUMN "MKT_SCR" TYPE NUMERIC(10,4),ALTER COLUMN "RISK_SCR" TYPE NUMERIC(10,4),ALTER COLUMN "CALC_SEQ" SET NOT NULL,ALTER COLUMN "MKT_SNAP_CD" SET NOT NULL,ALTER COLUMN "RISK_GRADE" SET NOT NULL,ALTER COLUMN "OVR_DEC_SIG" SET NOT NULL,ALTER COLUMN "EXEC_YN" SET NOT NULL,ALTER COLUMN "CONF_RT" SET NOT NULL,ALTER COLUMN "DATA_STS" SET NOT NULL,ALTER COLUMN "RULE_VER_NO" SET NOT NULL,ALTER COLUMN "LATEST_YN" SET NOT NULL,ALTER COLUMN "CALC_DTTM" SET NOT NULL,ALTER COLUMN "CRT_DTTM" SET NOT NULL,
 ADD CONSTRAINT "PK_TB_INV_DEC" PRIMARY KEY("INV_DEC_ID"),ADD CONSTRAINT "UK_TB_INV_DEC_01" UNIQUE("BASE_DT","CALC_SEQ","ACCT_ID","MKT_SNAP_CD"),ADD CONSTRAINT "FK_TB_INV_DEC_01" FOREIGN KEY("ACCT_ID") REFERENCES "TB_ACCT"("ACCT_ID"),
 ADD CONSTRAINT "CK_TB_INV_DEC_01" CHECK("CALC_SEQ">0),ADD CONSTRAINT "CK_TB_INV_DEC_02" CHECK("MKT_REGIME" IN ('OVERHEATED','NORMAL','MILD_CORRECTION','STRONG_CORRECTION','CRASH_RISK')),ADD CONSTRAINT "CK_TB_INV_DEC_03" CHECK("SENT_PHASE" IS NULL OR "SENT_PHASE" IN ('GREED','OPTIMISM','NEUTRAL','FATIGUE','FEAR','PANIC')),ADD CONSTRAINT "CK_TB_INV_DEC_04" CHECK("RISK_GRADE" IN ('LOW','MEDIUM','HIGH','CRITICAL')),ADD CONSTRAINT "CK_TB_INV_DEC_05" CHECK("CASH_RT" IS NULL OR "CASH_RT" BETWEEN 0 AND 100),ADD CONSTRAINT "CK_TB_INV_DEC_06" CHECK("TGT_CASH_RT" IS NULL OR "TGT_CASH_RT" BETWEEN 0 AND 100),ADD CONSTRAINT "CK_TB_INV_DEC_07" CHECK("OVR_DEC_SIG" IN ('HOLD_CASH','KEEP_REGULAR_BUY','REDUCE_REGULAR_BUY','INCREASE_REGULAR_BUY','SELECTIVE_ADD_BUY','PAUSE_BUY')),ADD CONSTRAINT "CK_TB_INV_DEC_08" CHECK("EXEC_YN" IN ('Y','N')),ADD CONSTRAINT "CK_TB_INV_DEC_09" CHECK("CONF_RT" BETWEEN 0 AND 100),ADD CONSTRAINT "CK_TB_INV_DEC_10" CHECK("DATA_STS" IN ('FRESH','STALE','MISSING','PARTIAL','ERROR')),ADD CONSTRAINT "CK_TB_INV_DEC_11" CHECK("LATEST_YN" IN ('Y','N'));
CREATE INDEX "IDX_TB_INV_DEC_01" ON "TB_INV_DEC"("BASE_DT" DESC); CREATE INDEX "IDX_TB_INV_DEC_02" ON "TB_INV_DEC"("ACCT_ID","BASE_DT" DESC); CREATE INDEX "IDX_TB_INV_DEC_03" ON "TB_INV_DEC"("MKT_REGIME","BASE_DT" DESC); CREATE INDEX "IDX_TB_INV_DEC_04" ON "TB_INV_DEC"("LATEST_YN","BASE_DT" DESC); CREATE UNIQUE INDEX "UK_TB_INV_DEC_LATEST" ON "TB_INV_DEC"("BASE_DT",COALESCE("ACCT_ID",0),"MKT_SNAP_CD") WHERE "LATEST_YN"='Y';
COMMENT ON TABLE "TB_INV_DEC" IS '기준일별 시장 및 계좌 종합 투자판단'; COMMENT ON COLUMN "TB_INV_DEC"."INV_DEC_ID" IS '투자판단 ID'; COMMENT ON COLUMN "TB_INV_DEC"."BASE_DT" IS '투자판단 기준일'; COMMENT ON COLUMN "TB_INV_DEC"."CALC_SEQ" IS '같은 기준일의 계산순번'; COMMENT ON COLUMN "TB_INV_DEC"."ACCT_ID" IS '계좌 ID(NULL이면 시장 전체 판단)'; COMMENT ON COLUMN "TB_INV_DEC"."MKT_SNAP_CD" IS '대상 시장 스냅샷 코드'; COMMENT ON COLUMN "TB_INV_DEC"."MKT_SCR" IS '시장 종합점수'; COMMENT ON COLUMN "TB_INV_DEC"."MKT_REGIME" IS '시장국면'; COMMENT ON COLUMN "TB_INV_DEC"."SENT_SCR" IS '시장심리 점수'; COMMENT ON COLUMN "TB_INV_DEC"."SENT_PHASE" IS '시장심리 단계'; COMMENT ON COLUMN "TB_INV_DEC"."RISK_SCR" IS '종합 위험점수'; COMMENT ON COLUMN "TB_INV_DEC"."RISK_GRADE" IS '종합 위험등급'; COMMENT ON COLUMN "TB_INV_DEC"."CASH_AMT" IS '계좌 일반 현금'; COMMENT ON COLUMN "TB_INV_DEC"."RSV_CASH_AMT" IS '계좌 추가매수 대기현금'; COMMENT ON COLUMN "TB_INV_DEC"."TOT_AST_AMT" IS '계좌 총자산'; COMMENT ON COLUMN "TB_INV_DEC"."CASH_RT" IS '계좌 전체 현금비중'; COMMENT ON COLUMN "TB_INV_DEC"."TGT_CASH_RT" IS '계좌 목표 현금비중'; COMMENT ON COLUMN "TB_INV_DEC"."BUY_CAP_AMT" IS '사용 가능한 총 매수금액'; COMMENT ON COLUMN "TB_INV_DEC"."REG_BUY_BGT_AMT" IS '정기매수 예산'; COMMENT ON COLUMN "TB_INV_DEC"."ADD_BUY_BGT_AMT" IS '추가매수 예산'; COMMENT ON COLUMN "TB_INV_DEC"."REG_BUY_TOT_AMT" IS '추천 정기매수 총액'; COMMENT ON COLUMN "TB_INV_DEC"."ADD_BUY_TOT_AMT" IS '추천 추가매수 총액'; COMMENT ON COLUMN "TB_INV_DEC"."RSV_ADD_AMT" IS '정기매수 감액으로 확보할 대기현금'; COMMENT ON COLUMN "TB_INV_DEC"."OVR_DEC_SIG" IS '종합 행동신호'; COMMENT ON COLUMN "TB_INV_DEC"."EXEC_YN" IS '실행 여부'; COMMENT ON COLUMN "TB_INV_DEC"."EXEC_RSN" IS '실행 또는 미실행 사유'; COMMENT ON COLUMN "TB_INV_DEC"."CONF_RT" IS '종합 판단 신뢰도'; COMMENT ON COLUMN "TB_INV_DEC"."KEY_RSN" IS '종합 판단 핵심근거'; COMMENT ON COLUMN "TB_INV_DEC"."DATA_STS" IS '입력 데이터 상태'; COMMENT ON COLUMN "TB_INV_DEC"."RULE_VER_NO" IS '계산규칙 버전'; COMMENT ON COLUMN "TB_INV_DEC"."LATEST_YN" IS '같은 기준일의 최신 계산 여부'; COMMENT ON COLUMN "TB_INV_DEC"."CALC_DTTM" IS '계산일시'; COMMENT ON COLUMN "TB_INV_DEC"."CRT_DTTM" IS '생성일시'; COMMENT ON COLUMN "TB_INV_DEC"."CRT_USR_ID" IS '생성자 ID';

DROP VIEW tb_stk_dec;
ALTER TABLE "TB_STK_DEC" RENAME COLUMN "ID" TO "STK_DEC_ID"; ALTER TABLE "TB_STK_DEC" RENAME COLUMN "MULT" TO "FINAL_MULT"; ALTER TABLE "TB_STK_DEC" RENAME COLUMN "MIN_BUY_AMT" TO "BASE_BUY_AMT"; ALTER TABLE "TB_STK_DEC" RENAME COLUMN "RCM_BUY_AMT" TO "REG_BUY_AMT"; ALTER TABLE "TB_STK_DEC" RENAME COLUMN "RSV_CASH" TO "SAVED_AMT";
ALTER TABLE "TB_STK_DEC" ADD COLUMN "ACCT_ID" BIGINT,ADD COLUMN "STK_ID" BIGINT,ADD COLUMN "HOLD_ID" BIGINT,ADD COLUMN "BASE_DT" DATE,ADD COLUMN "CUR_PRC" NUMERIC(20,6),ADD COLUMN "AVG_PRC" NUMERIC(20,6),ADD COLUMN "PL_RT" NUMERIC(10,4),ADD COLUMN "STK_DD_RT" NUMERIC(10,4),ADD COLUMN "MKT_DD_RT" NUMERIC(10,4),ADD COLUMN "REL_PERF_RT" NUMERIC(10,4),ADD COLUMN "TGT_WGT" NUMERIC(7,4),ADD COLUMN "CUR_WGT" NUMERIC(7,4),ADD COLUMN "WGT_STS" VARCHAR(20),ADD COLUMN "FUND_SCR" NUMERIC(10,4),ADD COLUMN "VALU_SCR" NUMERIC(10,4),ADD COLUMN "MOM_SCR" NUMERIC(10,4),ADD COLUMN "RISK_SCR" NUMERIC(10,4),ADD COLUMN "RISK_GRADE" VARCHAR(20),ADD COLUMN "MKT_MULT" NUMERIC(8,4),ADD COLUMN "STK_ADJ_MULT" NUMERIC(8,4),ADD COLUMN "WGT_ADJ_MULT" NUMERIC(8,4),ADD COLUMN "RISK_ADJ_MULT" NUMERIC(8,4),ADD COLUMN "EXEC_YN" CHAR(1) DEFAULT 'N',ADD COLUMN "EXEC_AMT" NUMERIC(20,4),ADD COLUMN "EXEC_RSN" VARCHAR(1000),ADD COLUMN "PRIO_NO" INTEGER,ADD COLUMN "CONF_RT" NUMERIC(10,4),ADD COLUMN "DEC_RSN" VARCHAR(2000),ADD COLUMN "RULE_VER_NO" INTEGER DEFAULT 1,ADD COLUMN "CRT_DTTM" TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP;
UPDATE "TB_STK_DEC" d SET "ACCT_ID"=a."ACCT_ID","STK_ID"=s."STK_ID","HOLD_ID"=h."HOLD_ID","BASE_DT"=i."BASE_DT","CUR_PRC"=h."CUR_PRC","AVG_PRC"=h."AVG_PRC","PL_RT"=h."PL_RT","TGT_WGT"=h."TGT_WGT","CUR_WGT"=h."CUR_WGT","WGT_STS"=h."WGT_STS","RISK_SCR"=i."RISK_SCR","RISK_GRADE"=i."RISK_GRADE","MKT_MULT"=d."FINAL_MULT","CONF_RT"=i."CONF_RT","DEC_RSN"=d."ADJ_RSN","CRT_DTTM"=d."REG_DT" AT TIME ZONE 'Asia/Seoul' FROM "TB_INV_DEC" i JOIN "TB_ACCT" a ON TRUE JOIN "TB_STK" s ON TRUE LEFT JOIN "TB_HOLD" h ON h."STK_ID"=s."STK_ID" AND h."ACCT_ID"=a."ACCT_ID" WHERE i."INV_DEC_ID"=d."INV_DEC_ID" AND a."ACCT_CD"=CASE WHEN s."MKT_CD"='US' THEN 'OVERSEAS_MAIN' ELSE 'DOMESTIC_MAIN' END AND s."STK_CD"=d."STK_CD";
ALTER TABLE "TB_STK_DEC" DROP CONSTRAINT "tb_investment_stock_decision_pkey";
ALTER TABLE "TB_STK_DEC" ALTER COLUMN "ACCT_ID" SET NOT NULL,ALTER COLUMN "STK_ID" SET NOT NULL,ALTER COLUMN "BASE_DT" SET NOT NULL,ALTER COLUMN "RISK_SCR" SET NOT NULL,ALTER COLUMN "RISK_GRADE" SET NOT NULL,ALTER COLUMN "EXEC_YN" SET NOT NULL,ALTER COLUMN "CONF_RT" SET NOT NULL,ALTER COLUMN "RULE_VER_NO" SET NOT NULL,ALTER COLUMN "CRT_DTTM" SET NOT NULL,
 ADD CONSTRAINT "PK_TB_STK_DEC" PRIMARY KEY("STK_DEC_ID"),ADD CONSTRAINT "FK_TB_STK_DEC_01" FOREIGN KEY("INV_DEC_ID") REFERENCES "TB_INV_DEC"("INV_DEC_ID"),ADD CONSTRAINT "UK_TB_STK_DEC_01" UNIQUE("INV_DEC_ID","ACCT_ID","STK_ID"),ADD CONSTRAINT "FK_TB_STK_DEC_02" FOREIGN KEY("ACCT_ID") REFERENCES "TB_ACCT"("ACCT_ID"),ADD CONSTRAINT "FK_TB_STK_DEC_03" FOREIGN KEY("STK_ID") REFERENCES "TB_STK"("STK_ID"),ADD CONSTRAINT "FK_TB_STK_DEC_04" FOREIGN KEY("HOLD_ID") REFERENCES "TB_HOLD"("HOLD_ID"),ADD CONSTRAINT "CK_TB_STK_DEC_01" CHECK("WGT_STS" IS NULL OR "WGT_STS" IN ('UNDERWEIGHT','NORMAL','OVERWEIGHT')),ADD CONSTRAINT "CK_TB_STK_DEC_02" CHECK("RISK_GRADE" IN ('LOW','MEDIUM','HIGH','CRITICAL')),ADD CONSTRAINT "CK_TB_STK_DEC_03" CHECK("FINAL_MULT" IS NULL OR "FINAL_MULT">=0),ADD CONSTRAINT "CK_TB_STK_DEC_04" CHECK("REG_BUY_AMT" IS NULL OR "REG_BUY_AMT">=0),ADD CONSTRAINT "CK_TB_STK_DEC_05" CHECK("SAVED_AMT" IS NULL OR "SAVED_AMT">=0),ADD CONSTRAINT "CK_TB_STK_DEC_06" CHECK("ACT_SIG" IN ('PAUSE','REDUCE','KEEP_MINIMUM','INCREASE','ADDITIONAL_BUY','REBUY','REBALANCE_SELL','HOLD')),ADD CONSTRAINT "CK_TB_STK_DEC_07" CHECK("EXEC_YN" IN ('Y','N')),ADD CONSTRAINT "CK_TB_STK_DEC_08" CHECK("EXEC_AMT" IS NULL OR "EXEC_AMT">=0),ADD CONSTRAINT "CK_TB_STK_DEC_09" CHECK("CONF_RT" BETWEEN 0 AND 100);
CREATE INDEX "IDX_TB_STK_DEC_01" ON "TB_STK_DEC"("INV_DEC_ID"); CREATE INDEX "IDX_TB_STK_DEC_02" ON "TB_STK_DEC"("ACCT_ID","BASE_DT" DESC); CREATE INDEX "IDX_TB_STK_DEC_03" ON "TB_STK_DEC"("STK_ID","BASE_DT" DESC); CREATE INDEX "IDX_TB_STK_DEC_04" ON "TB_STK_DEC"("ACT_SIG","BASE_DT" DESC); CREATE INDEX "IDX_TB_STK_DEC_05" ON "TB_STK_DEC"("PRIO_NO");
COMMENT ON TABLE "TB_STK_DEC" IS '투자판단 실행별 종목 투자판단'; COMMENT ON COLUMN "TB_STK_DEC"."STK_DEC_ID" IS '종목판단 ID'; COMMENT ON COLUMN "TB_STK_DEC"."INV_DEC_ID" IS '상위 투자판단 ID'; COMMENT ON COLUMN "TB_STK_DEC"."ACCT_ID" IS '계좌 ID'; COMMENT ON COLUMN "TB_STK_DEC"."STK_ID" IS '종목 ID'; COMMENT ON COLUMN "TB_STK_DEC"."HOLD_ID" IS '보유종목 ID'; COMMENT ON COLUMN "TB_STK_DEC"."BASE_DT" IS '종목판단 기준일'; COMMENT ON COLUMN "TB_STK_DEC"."CUR_PRC" IS '판단 시점 현재가'; COMMENT ON COLUMN "TB_STK_DEC"."AVG_PRC" IS '판단 시점 평단가'; COMMENT ON COLUMN "TB_STK_DEC"."PL_RT" IS '판단 시점 손익률'; COMMENT ON COLUMN "TB_STK_DEC"."STK_DD_RT" IS '종목 고점 대비 하락률'; COMMENT ON COLUMN "TB_STK_DEC"."MKT_DD_RT" IS '기준지수 고점 대비 하락률'; COMMENT ON COLUMN "TB_STK_DEC"."REL_PERF_RT" IS '종목의 기준지수 대비 상대성과'; COMMENT ON COLUMN "TB_STK_DEC"."TGT_WGT" IS '종목 목표비중'; COMMENT ON COLUMN "TB_STK_DEC"."CUR_WGT" IS '종목 현재비중'; COMMENT ON COLUMN "TB_STK_DEC"."WGT_STS" IS '비중상태'; COMMENT ON COLUMN "TB_STK_DEC"."FUND_SCR" IS '종목 펀더멘털 점수'; COMMENT ON COLUMN "TB_STK_DEC"."VALU_SCR" IS '종목 밸류에이션 점수'; COMMENT ON COLUMN "TB_STK_DEC"."MOM_SCR" IS '종목 모멘텀 점수'; COMMENT ON COLUMN "TB_STK_DEC"."RISK_SCR" IS '종목 위험점수'; COMMENT ON COLUMN "TB_STK_DEC"."RISK_GRADE" IS '종목 위험등급'; COMMENT ON COLUMN "TB_STK_DEC"."MKT_MULT" IS '시장 기본 매수배수'; COMMENT ON COLUMN "TB_STK_DEC"."STK_ADJ_MULT" IS '종목 보정배수'; COMMENT ON COLUMN "TB_STK_DEC"."WGT_ADJ_MULT" IS '비중 보정배수'; COMMENT ON COLUMN "TB_STK_DEC"."RISK_ADJ_MULT" IS '위험 보정배수'; COMMENT ON COLUMN "TB_STK_DEC"."FINAL_MULT" IS '최종 적용 매수배수'; COMMENT ON COLUMN "TB_STK_DEC"."BASE_BUY_AMT" IS '감액 전 기준 정기매수금액'; COMMENT ON COLUMN "TB_STK_DEC"."REG_BUY_AMT" IS '추천 정기매수금액'; COMMENT ON COLUMN "TB_STK_DEC"."SAVED_AMT" IS '정기매수 감액으로 확보한 금액'; COMMENT ON COLUMN "TB_STK_DEC"."ACT_SIG" IS '종목 행동신호'; COMMENT ON COLUMN "TB_STK_DEC"."EXEC_YN" IS '실행 여부'; COMMENT ON COLUMN "TB_STK_DEC"."EXEC_AMT" IS '실행 예정 또는 실행 금액'; COMMENT ON COLUMN "TB_STK_DEC"."EXEC_RSN" IS '실행 또는 미실행 사유'; COMMENT ON COLUMN "TB_STK_DEC"."PRIO_NO" IS '실행 우선순위'; COMMENT ON COLUMN "TB_STK_DEC"."CONF_RT" IS '종목판단 신뢰도'; COMMENT ON COLUMN "TB_STK_DEC"."DEC_RSN" IS '종목판단 근거'; COMMENT ON COLUMN "TB_STK_DEC"."RULE_VER_NO" IS '계산규칙 버전'; COMMENT ON COLUMN "TB_STK_DEC"."CRT_DTTM" IS '생성일시';

CREATE TABLE "TB_DEC_CHG"("DEC_CHG_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY,"STK_DEC_ID" BIGINT NOT NULL,"PREV_STK_DEC_ID" BIGINT,"BASE_DT" DATE NOT NULL,"CHG_TP" VARCHAR(30) NOT NULL,"PREV_ACT_SIG" VARCHAR(30),"CUR_ACT_SIG" VARCHAR(30),"PREV_MULT" NUMERIC(8,4),"CUR_MULT" NUMERIC(8,4),"PREV_BUY_AMT" NUMERIC(20,4),"CUR_BUY_AMT" NUMERIC(20,4),"PREV_RISK_GRADE" VARCHAR(20),"CUR_RISK_GRADE" VARCHAR(20),"PREV_WGT_STS" VARCHAR(20),"CUR_WGT_STS" VARCHAR(20),"CHG_RSN" VARCHAR(2000),"CRT_DTTM" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PK_TB_DEC_CHG" PRIMARY KEY("DEC_CHG_ID"),CONSTRAINT "FK_TB_DEC_CHG_01" FOREIGN KEY("STK_DEC_ID") REFERENCES "TB_STK_DEC"("STK_DEC_ID"),CONSTRAINT "FK_TB_DEC_CHG_02" FOREIGN KEY("PREV_STK_DEC_ID") REFERENCES "TB_STK_DEC"("STK_DEC_ID"),CONSTRAINT "CK_TB_DEC_CHG_01" CHECK("CHG_TP" IN ('NEW','SIGNAL_CHANGE','AMOUNT_CHANGE','MULTIPLIER_CHANGE','RISK_CHANGE','WEIGHT_CHANGE','EXECUTION_CHANGE')));
CREATE INDEX "IDX_TB_DEC_CHG_01" ON "TB_DEC_CHG"("STK_DEC_ID"); CREATE INDEX "IDX_TB_DEC_CHG_02" ON "TB_DEC_CHG"("BASE_DT" DESC); CREATE INDEX "IDX_TB_DEC_CHG_03" ON "TB_DEC_CHG"("CHG_TP","BASE_DT" DESC);
COMMENT ON TABLE "TB_DEC_CHG" IS '종목 투자판단 변경이력'; COMMENT ON COLUMN "TB_DEC_CHG"."DEC_CHG_ID" IS '판단 변경이력 ID'; COMMENT ON COLUMN "TB_DEC_CHG"."STK_DEC_ID" IS '현재 종목판단 ID'; COMMENT ON COLUMN "TB_DEC_CHG"."PREV_STK_DEC_ID" IS '직전 종목판단 ID'; COMMENT ON COLUMN "TB_DEC_CHG"."BASE_DT" IS '현재 판단 기준일'; COMMENT ON COLUMN "TB_DEC_CHG"."CHG_TP" IS '판단 변경 유형'; COMMENT ON COLUMN "TB_DEC_CHG"."PREV_ACT_SIG" IS '이전 행동신호'; COMMENT ON COLUMN "TB_DEC_CHG"."CUR_ACT_SIG" IS '현재 행동신호'; COMMENT ON COLUMN "TB_DEC_CHG"."PREV_MULT" IS '이전 최종 매수배수'; COMMENT ON COLUMN "TB_DEC_CHG"."CUR_MULT" IS '현재 최종 매수배수'; COMMENT ON COLUMN "TB_DEC_CHG"."PREV_BUY_AMT" IS '이전 추천매수금액'; COMMENT ON COLUMN "TB_DEC_CHG"."CUR_BUY_AMT" IS '현재 추천매수금액'; COMMENT ON COLUMN "TB_DEC_CHG"."PREV_RISK_GRADE" IS '이전 위험등급'; COMMENT ON COLUMN "TB_DEC_CHG"."CUR_RISK_GRADE" IS '현재 위험등급'; COMMENT ON COLUMN "TB_DEC_CHG"."PREV_WGT_STS" IS '이전 비중상태'; COMMENT ON COLUMN "TB_DEC_CHG"."CUR_WGT_STS" IS '현재 비중상태'; COMMENT ON COLUMN "TB_DEC_CHG"."CHG_RSN" IS '판단 변경 사유'; COMMENT ON COLUMN "TB_DEC_CHG"."CRT_DTTM" IS '생성일시';

