CREATE INDEX "IDX_TB_ADD_BUY_01" ON "TB_ADD_BUY"("ACCT_ID","BASE_DT" DESC); CREATE INDEX "IDX_TB_ADD_BUY_02" ON "TB_ADD_BUY"("ELIG_YN","PRIO_NO"); CREATE INDEX "IDX_TB_ADD_BUY_03" ON "TB_ADD_BUY"("STK_ID","BASE_DT" DESC);
