CREATE INDEX "IDX_TB_REBUY_01" ON "TB_REBUY"("ACCT_ID","BASE_DT" DESC); CREATE INDEX "IDX_TB_REBUY_02" ON "TB_REBUY"("REBUY_SIG","PRIO_NO"); CREATE INDEX "IDX_TB_REBUY_03" ON "TB_REBUY"("STK_ID","BASE_DT" DESC);
